// Path constants

// Pending macros migrated; use `networkPending.*` fields.

void ofApp::triggerCameraShake(float intensity, float duration) {
	cameraShakeIntensity = intensity * 0.6f;
	cameraShakeDuration = std::max(0.001f, duration);
	cameraShakeTimer = cameraShakeDuration;
	// Seed a small initial offset
	std::uniform_real_distribution<float> off(-1.0f, 1.0f);
	cameraShakeOffset = glm::vec3(off(visualRNG), off(visualRNG) * 0.5f, off(visualRNG)) * cameraShakeIntensity;
}

// Resolve the game's root directory. Falls back to the current working directory.
static std::filesystem::path getGameRootPath() {
	try {
		std::filesystem::path cwd = std::filesystem::current_path();
		if (cwd.filename() == "bin") return cwd.parent_path();
		return cwd;
	} catch (...) {
		return std::filesystem::current_path();
	}
}

static std::filesystem::path getSavesDirPath() {
	return getGameRootPath() / std::filesystem::path("Saves");
}

static std::string makeSavePath(const std::string & p) {
	if (!p.empty() && p.front() == '/') return p;
	return (getSavesDirPath() / std::filesystem::path(p)).string();
}

void ofApp::playHandFeedbackSfx(float speed, float volumeMul) {
	if (footstepSounds.empty()) return;
	float nowSec = ofGetElapsedTimef();
	if (nowSec < nextHandSfxAt) return;

	std::uniform_int_distribution<int> soundIdx(0, (int)footstepSounds.size() - 1);
	int idx = soundIdx(visualRNG);
	float vol = std::clamp(settingsMasterVolume * settingsSfxVolume * volumeMul, 0.0f, 1.0f);
	footstepSounds[idx].setSpeed(std::clamp(speed, 0.70f, 1.50f));
	footstepSounds[idx].setVolume(vol);
	footstepSounds[idx].play();
	nextHandSfxAt = nowSec + 0.045f;
}

