struct UILayoutSpacing {
	float edgeInset = 0.0f; // outer edge inset for gameplay HUD anchoring
	float stackYOffset = 0.0f; // downward visual nudge for deck/discard stack
	float stackVerticalGap = 0.0f; // vertical spacing between discard/deck cards
	float minionEntryGapUnscaled = 12.0f; // logical row gap before per-resolution scale
	float minionIconGap = 0.0f; // spacing between minion deck/discard icons
	float timerBarHeight = 0.0f; // reserved top band for turn timer
	float chatInset = 0.0f; // default chat inset from top/left edge
	float healthBarSideGap = 0.0f; // gap between deck and health bar
	float healthBarInwardNudge = 0.0f; // extra nudge to avoid overlap
};

static UILayoutSpacing buildUILayoutSpacing(float scale, bool turnTimerEnabled) {
	UILayoutSpacing ui;
	ui.edgeInset = 20.0f * scale;
	ui.stackYOffset = 12.0f * scale;
	ui.stackVerticalGap = 20.0f * scale;
	ui.minionEntryGapUnscaled = 20.0f;
	ui.minionIconGap = 6.0f * scale;
	ui.timerBarHeight = turnTimerEnabled ? (8.0f * scale) : 0.0f;
	ui.chatInset = 8.0f * scale;
	ui.healthBarSideGap = 8.0f * scale;
	ui.healthBarInwardNudge = 12.0f * scale;
	return ui;
}

// Global UI scale helper: 1440p baseline (1.0 at 1440p). Clamped to avoid extreme sizes.
static inline float getUIScaleFromHeight(float screenH) {
	float s = screenH / 1440.0f;
	return std::clamp(s, 0.5f, 1.25f);
}

static inline float getHandCardVisualBoost(float screenH) {
	float boost = 1.15f - ((screenH - 1080.0f) * (0.15f / 360.0f));
	return std::clamp(boost, 1.0f, 1.15f);
}

static float effectiveBottomGap(const UILayoutSpacing & ui) {
	return std::max(0.0f, ui.edgeInset - ui.stackYOffset);
}

struct HandLayout {
	float cardW = kCardPixelWidth * kHandCardVisualScale;
	float cardH = kCardPixelHeight * kHandCardVisualScale;
	float spacing = 0.0f;
	float totalWidth = 0.0f;
	float startX = 0.0f;
	float restY = 0.0f;
	ofRectangle handAreaRect;
};

static ofRectangle computeHandAreaRect(float screenW, float screenH) {
	float scale = getUIScaleFromHeight(screenH);
	float handBoost = getHandCardVisualBoost(screenH);
	UILayoutSpacing ui = buildUILayoutSpacing(scale, true);

	float handCardH = kCardPixelHeight * kHandCardVisualScale * handBoost * scale;

	// Exact UI metrics
	float staticUICardWidth = (kCardPixelWidth * pileCardScale) * scale;
	float deckBottomGap = effectiveBottomGap(ui);
	float sideInset = deckBottomGap;
	float healthBarW = 220.0f * scale;
	float gap = ui.healthBarSideGap;
	float healthBarInwardNudge = ui.healthBarInwardNudge;

	// Find the exact inner edges of the Left and Right HP bars
	float p0_healthRight = sideInset + staticUICardWidth + gap + healthBarInwardNudge + healthBarW;
	float p1_healthLeft = screenW - staticUICardWidth - sideInset - gap - healthBarW - healthBarInwardNudge;

	// Squeeze the box so it physically cannot touch the HP bars
	float padding = 150.0f * scale; // Shrinks the box inward by an extra 70px on both sides
	float left = p0_healthRight + padding;
	float right = p1_healthLeft - padding;

	float handAreaWidth = std::max(0.0f, right - left);

	float restY = screenH - 80.0f * scale;
	float top = restY - (handCardH * 0.5f) - (56.0f * scale);
	float bottom = screenH - (8.0f * scale);

	return ofRectangle(left, top, handAreaWidth, std::max(0.0f, bottom - top));
}

static HandLayout computeHandLayout(size_t numCards, float screenW, float screenH) {
	HandLayout l;
	float scale = getUIScaleFromHeight(screenH);
	float handBoost = getHandCardVisualBoost(screenH);
	l.cardW = kCardPixelWidth * kHandCardVisualScale * handBoost * scale;
	l.cardH = kCardPixelHeight * kHandCardVisualScale * handBoost * scale;
	l.handAreaRect = computeHandAreaRect(screenW, screenH);
	l.restY = screenH - 80.0f * scale;
	if (numCards <= 1) {
		l.spacing = 0.0f;
		l.totalWidth = l.cardW;
		l.startX = l.handAreaRect.getCenter().x - (l.totalWidth * 0.5f);
		return l;
	}

	float handAreaWidth = std::max(0.0f, l.handAreaRect.getWidth());
	float smallGap = std::clamp(screenH * 0.008f * scale, 6.0f * scale, 12.0f * scale);

	if (numCards <= 3) {
		// 1-3 cards: keep cards adjacent (no overlap), with a small positive gap.
		l.spacing = smallGap;
	} else {
		// 4+ cards: always overlap (Hearthstone-like fan), while still fitting.
		float centerStepToFit = (handAreaWidth - l.cardW) / (float)(numCards - 1);
		float minCenterStep = 1.0f;
		float maxCenterStep = std::max(1.0f, l.cardW - std::max(8.0f * scale, screenH * 0.006f * scale)); // force overlap
		float centerStep = ofClamp(centerStepToFit, minCenterStep, maxCenterStep);
		l.spacing = centerStep - l.cardW;
	}

	l.totalWidth = (float)numCards * l.cardW + (float)(numCards - 1) * l.spacing;
	l.startX = l.handAreaRect.getCenter().x - (l.totalWidth * 0.5f);
	return l;
}

static int getEffectiveCardCostForPlayer(const Player & player, const Card & card) {
	int costToPay = card.cost;
	if (card.type == CARD_KICK && player.freeKickTurns > 0) costToPay = 0;
	return costToPay;
}

// Centralized flat damage resolver for migrated cards.
// Uses new baseDamage when present and falls back to legacy value.

// Centralized damage dice resolver for migrated cards.
// Uses damageDice* first, then legacy numDice/diceSides.
static std::pair<int, int> getCardDamageDice(const Card & card, int fallbackNum = 0, int fallbackSides = 0) {
	if (card.damageDiceNum > 0 && card.damageDiceSides > 0) return { card.damageDiceNum, card.damageDiceSides };
	if (card.numDice > 0 && card.diceSides > 0) return { card.numDice, card.diceSides };
	return { fallbackNum, fallbackSides };
}

// Centralized range dice resolver.
// Range remains on legacy numDice/diceSides for now.
static std::pair<int, int> getCardRangeDice(const Card & card, int fallbackNum = 0, int fallbackSides = 0) {
	if (card.rangeDiceNum > 0 && card.rangeDiceSides > 0) return { card.rangeDiceNum, card.rangeDiceSides };
	if (card.numDice > 0 && card.diceSides > 0) return { card.numDice, card.diceSides };
	return { fallbackNum, fallbackSides };
}

// Centralized utility dice resolver for non-range, non-damage effects.
static std::pair<int, int> getCardUtilityDice(const Card & card, int fallbackNum = 0, int fallbackSides = 0) {
	if (card.utilityDiceNum > 0 && card.utilityDiceSides > 0) return { card.utilityDiceNum, card.utilityDiceSides };
	if (card.numDice > 0 && card.diceSides > 0) return { card.numDice, card.diceSides };
	return { fallbackNum, fallbackSides };
}

// Centralized summon dice resolver for HP/count rolls.
[[maybe_unused]] static std::pair<int, int> getCardSummonDice(const Card & card, int fallbackNum = 0, int fallbackSides = 0) {
	if (card.summonDiceNum > 0 && card.summonDiceSides > 0) return { card.summonDiceNum, card.summonDiceSides };
	if (card.numDice > 0 && card.diceSides > 0) return { card.numDice, card.diceSides };
	return { fallbackNum, fallbackSides };
}

