// ==============================================================================
// DEEP REINFORCEMENT LEARNING AI AGENT SCAFFOLDING
// ==============================================================================

void ofApp::updateAI() {
	if (!isVsAI && !isAIvsAI) return;
	if (isVsAI && !isAIvsAI && !isMyTurn()) return;

	if (endTurnLocked || g_isGameOver) return;

	bool isGameBusy = false;
	if (isProcessingEffect || isEarthquakeActive || isPlayerAnimating) isGameBusy = true;
	for (const auto & roll : activeDiceRolls) {
		if (!roll.isFinishedVisual) isGameBusy = true;
	}

	// CRITICAL FIX: Allow AI to act when it needs to click a target or place a unit!
	if (cardPlayState != CARD_PLAY_STATE_IDLE && cardInteractionState != CARD_INTERACTION_STATE_MENU && cardInteractionState != CARD_INTERACTION_STATE_TARGETING && cardInteractionState != CARD_INTERACTION_STATE_PLACING) {
		isGameBusy = true;
	}

	if (currentState == STATE_DRAFTING && draftOptions.empty()) isGameBusy = true;

	if (isGameBusy) return;

	// If watching the AI play normally (not headless), add a tiny delay
	if (!headless) {
		aiThinkTimer -= ofGetLastFrameTime();
		if (aiThinkTimer > 0.0f) return;
		aiThinkTimer = 0.05f;
	}

	std::vector<float> stateVector = extractGameStateForAI();
	float rewardToSend = cumulativeReward;
	cumulativeReward = 0.0f;

	int actionIndex = getAIActionFromModel(stateVector, rewardToSend, false);
	executeAIAction(actionIndex);
}

std::vector<float> ofApp::extractGameStateForAI() {
	std::vector<float> state;
	state.reserve(5700); // Reserve memory to prevent slow allocations

	// --- 1. GLOBAL STATE (5 floats) ---
	state.push_back((float)globalTurnCounter);
	state.push_back((float)currentAP);
	state.push_back(isInGameDraft ? 1.0f : 0.0f);
	state.push_back((float)draftStage);
	state.push_back((float)draftPicksRemaining);

	// The Network needs to see the board from the perspective of whoever's turn it is
	int activeID = isAIvsAI ? (players[currentPlayerIndex].isMinion ? players[currentPlayerIndex].ownerID : players[currentPlayerIndex].playerID) : 1;
	int opponentID = (activeID == 1) ? 0 : 1;

	// --- 2. MAIN PLAYER STATES (32 floats total) ---
	auto encodePlayer = [&](int pID) {
		int idx = findPlayerIndexByID(pID);
		if (idx >= 0 && idx < (int)players.size()) {
			const Player & p = players[idx];
			state.push_back((float)p.health);
			state.push_back((float)p.maxHealth);
			state.push_back((float)p.block);
			state.push_back((float)p.ward);
			state.push_back((float)p.fortification);
			state.push_back((float)p.barrier);
			state.push_back((float)p.holyBlock);
			state.push_back((float)p.luck + computePassiveLuck(idx));
			state.push_back(p.onFire ? 1.0f : 0.0f);
			state.push_back(p.isPoisoned ? 1.0f : 0.0f);
			state.push_back(p.isParalyzed ? 1.0f : 0.0f);
			state.push_back((float)p.sleepTurnsRemaining);
			state.push_back(p.inTortoiseForm ? 1.0f : 0.0f);
			state.push_back(p.inGhostForm ? 1.0f : 0.0f);
			state.push_back((float)p.deck.size());
			state.push_back((float)p.discardPile.size());
		} else {
			for (int i = 0; i < 16; i++)
				state.push_back(0.0f);
		}
	};
	encodePlayer(activeID); // The AI making the decision
	encodePlayer(opponentID); // The Enemy

	// --- 3. AI HAND (70 floats: Bag of Cards) ---
	std::vector<float> handCounts(70, 0.0f);
	int aiIdx = findPlayerIndexByID(activeID);
	if (aiIdx >= 0) {
		for (const Card & c : players[aiIdx].hand) {
			int cardId = (int)c.type - 1; // Assuming CARD_NONE is 0, cards are 1-70
			if (cardId >= 0 && cardId < 70) handCounts[cardId] += 1.0f;
		}
	}
	for (float f : handCounts)
		state.push_back(f);

	// --- 4. DRAFT OPTIONS (70 floats: Bag of Cards) ---
	// If drafting, tells the AI which cards are currently on screen to pick from.
	std::vector<float> draftCounts(70, 0.0f);
	if (currentState == STATE_DRAFTING) {
		for (const Card & c : draftOptions) {
			int cardId = (int)c.type - 1;
			if (cardId >= 0 && cardId < 70) draftCounts[cardId] += 1.0f;
		}
	}
	for (float f : draftCounts)
		state.push_back(f);

	// --- 5. BOARD SPATIAL GRID (165 tiles * 33 floats = 5445 floats) ---
	// This flattens the 15x11 grid so your Neural Network can run 2D Convolutions over it.
	for (int y = 0; y < BOARD_HEIGHT; ++y) {
		for (int x = 0; x < BOARD_WIDTH; ++x) {
			const Tile & t = board[x][y];

			// Environment (2 floats)
			state.push_back(t.hasWall ? 1.0f : 0.0f);
			state.push_back(t.isMagicWall ? 1.0f : 0.0f);

			// Keys (3 floats)
			float hasGold = 0, hasSilver = 0, hasBronze = 0;
			for (const auto & k : floatingKeyInstances) {
				if (k.pos.x == x && k.pos.y == y) {
					if (k.set == 1)
						hasGold = 1.0f;
					else if (k.set == 2)
						hasSilver = 1.0f;
					else if (k.set == 3)
						hasBronze = 1.0f;
				}
			}
			state.push_back(hasGold);
			state.push_back(hasSilver);
			state.push_back(hasBronze);

			// Occupancy (1 float)
			state.push_back(t.hasPlayer ? 1.0f : 0.0f);

			// Occupant Details (27 floats)
			bool foundOccupant = false;
			for (size_t i = 0; i < players.size(); ++i) {
				const Player & p = players[i];
				if (p.x == x && p.y == y && p.health > 0) {
					foundOccupant = true;

					// Ownership: 1.0 for AI team, -1.0 for Human team
					int owner = p.isMinion ? p.ownerID : p.playerID;
					state.push_back(owner == 1 ? 1.0f : -1.0f);

					// Unit Type One-Hot (12 floats)
					state.push_back(!p.isMinion ? 1.0f : 0.0f); // Main Player
					state.push_back(p.isKobold ? 1.0f : 0.0f);
					state.push_back(p.isWolf ? 1.0f : 0.0f);
					state.push_back(p.isHellhound ? 1.0f : 0.0f);
					state.push_back(p.isDemon ? 1.0f : 0.0f);
					state.push_back(p.isKoboldKing ? 1.0f : 0.0f);
					state.push_back(p.isAssistant ? 1.0f : 0.0f);
					state.push_back(p.isFaerie ? 1.0f : 0.0f);
					state.push_back(p.isGolem ? 1.0f : 0.0f);
					state.push_back(p.isSkeleton ? 1.0f : 0.0f);
					state.push_back((p.isWallUnit && !p.isMagicWallUnit) ? 1.0f : 0.0f);
					state.push_back(p.isMagicWallUnit ? 1.0f : 0.0f);

					// Combat Stats (7 floats)
					state.push_back((float)p.health);
					state.push_back((float)p.maxHealth);
					state.push_back((float)p.block);
					state.push_back((float)p.ward);
					state.push_back((float)p.fortification);
					state.push_back((float)p.barrier);
					state.push_back((float)p.holyBlock);

					// Status Effects (7 floats)
					state.push_back(p.onFire ? 1.0f : 0.0f);
					state.push_back(p.isPoisoned ? 1.0f : 0.0f);
					state.push_back(p.isParalyzed ? 1.0f : 0.0f);
					state.push_back((float)p.sleepTurnsRemaining);
					state.push_back(p.inTortoiseForm ? 1.0f : 0.0f);
					state.push_back(p.inGhostForm ? 1.0f : 0.0f);
					state.push_back(p.hasRegeneration ? 1.0f : 0.0f);

					break; // Only encode top occupant if multiple are somehow here
				}
			}

			// If empty, pad the occupant data with zeros to keep tensor shape strict
			if (!foundOccupant) {
				for (int i = 0; i < 27; ++i)
					state.push_back(0.0f);
			}
		}
	}

	return state;
}

int ofApp::getAIActionFromModel(const std::vector<float> & state, float reward, bool done) {
	if (!zmqConnected) {
		// Fallback random/basic logic if Python is not connected
		if (currentState == STATE_DRAFTING) return 30;
		if (cardInteractionState == CARD_INTERACTION_STATE_MENU) return 10;
		int activeID = isAIvsAI ? (players[currentPlayerIndex].isMinion ? players[currentPlayerIndex].ownerID : players[currentPlayerIndex].playerID) : 1;
		int aiIdx = findPlayerIndexByID(activeID);
		if (aiIdx >= 0) {
			Player & aiPlayer = players[aiIdx];
			bool hasDrawn = (activeID == myLocalPlayerID) ? hasDrawnCardsThisTurn : opponentHasDrawnCardsThisTurn;
			if (!hasDrawn && !aiPlayer.deck.empty()) return 1;
			for (int i = 0; i < (int)aiPlayer.hand.size(); ++i) {
				if (aiPlayer.ap >= aiPlayer.hand[i].cost) return 10000 + i * (BOARD_WIDTH * BOARD_HEIGHT);
			}
		}
		return 0; // End Turn
	}

	// --- 1. GENERATE ACTION MASK (20,000 Elements) ---
	std::vector<float> actionMask(20000, 0.0f);
	int activeID = isAIvsAI ? (players[currentPlayerIndex].isMinion ? players[currentPlayerIndex].ownerID : players[currentPlayerIndex].playerID) : 1;
	int aiIdx = findPlayerIndexByID(activeID);

	if (currentState == STATE_DRAFTING) {
		// Only Draft Combinations are valid
		actionMask[30] = 1.0f;
		actionMask[31] = 1.0f;
		actionMask[32] = 1.0f;
	} else if (cardInteractionState == CARD_INTERACTION_STATE_MENU) {
		// Only Menu UI interactions are valid
		for (int i = 10; i <= 29; i++)
			actionMask[i] = 1.0f;
		for (int i = 40; i <= 140; i++)
			actionMask[i] = 1.0f; // Amnesia/Renewed UI
	} else if (cardInteractionState == CARD_INTERACTION_STATE_TARGETING || cardInteractionState == CARD_INTERACTION_STATE_PLACING) {
		// Raw Targeting modes (Teleport, Spawn wolves, etc.)
		for (int y = 0; y < BOARD_HEIGHT; y++) {
			for (int x = 0; x < BOARD_WIDTH; x++) {
				if (board[x][y].isTargetable) {
					actionMask[1000 + y * BOARD_WIDTH + x] = 1.0f;
				}
			}
		}
	} else {
		// Gameplay Actions
		actionMask[0] = 1.0f; // End turn is always valid

		if (aiIdx >= 0) {
			Player & aiPlayer = players[aiIdx];

			// Can we draw?
			bool hasDrawn = (activeID == myLocalPlayerID) ? hasDrawnCardsThisTurn : opponentHasDrawnCardsThisTurn;
			if (!hasDrawn && !aiPlayer.deck.empty()) {
				actionMask[1] = 1.0f;
			}

			// Can we use Assistant AP Reroll?
			for (size_t i = 0; i < players.size(); i++) {
				if (players[i].isAssistant && players[i].health > 0 && players[i].directSummonerID == activeID && !players[i].assistantRerollUsedThisTurn) {
					if (abs(players[i].x - players[currentPlayerIndex].x) + abs(players[i].y - players[currentPlayerIndex].y) <= 1) {
						actionMask[2] = 1.0f;
						break;
					}
				}
			}

			// Movement Masking (Estimate valid tiles based on AP)
			for (int y = 0; y < BOARD_HEIGHT; y++) {
				for (int x = 0; x < BOARD_WIDTH; x++) {
					int dist = abs(x - aiPlayer.x) + abs(y - aiPlayer.y);
					if (dist > 0 && dist <= aiPlayer.ap && !board[x][y].hasWall && !board[x][y].hasPlayer) {
						actionMask[200 + y * BOARD_WIDTH + x] = 1.0f;
					}
				}
			}

			// Card Playing Masking
			int savedInteractionState = cardInteractionState;
			int savedInteractingCardIdx = interactingCardIndex;

			for (int i = 0; i < (int)aiPlayer.hand.size(); ++i) {
				int cost = getEffectiveCardCostForPlayer(aiPlayer, aiPlayer.hand[i]);
				if (aiPlayer.ap >= cost) {
					// Use existing game logic to find mathematically legal targets!
					interactingCardIndex = i;
					calculateTargetHighlights(i);
					bool hasTargets = false;

					for (int y = 0; y < BOARD_HEIGHT; y++) {
						for (int x = 0; x < BOARD_WIDTH; x++) {
							if (board[x][y].isTargetable) {
								actionMask[10000 + i * (BOARD_WIDTH * BOARD_HEIGHT) + (y * BOARD_WIDTH + x)] = 1.0f;
								hasTargets = true;
							}
						}
					}

					// Self-target fallback if board returns empty but card is valid (like Time Vortex)
					if (!hasTargets && (aiPlayer.hand[i].targeting == TARGET_NONE || aiPlayer.hand[i].targeting == TARGET_SELF)) {
						actionMask[10000 + i * (BOARD_WIDTH * BOARD_HEIGHT) + (aiPlayer.y * BOARD_WIDTH + aiPlayer.x)] = 1.0f;
					}
				}
			}

			// Restore Game Visual State
			cardInteractionState = (CardInteractionState)savedInteractionState;
			interactingCardIndex = savedInteractingCardIdx;
			calculateTargetHighlights(interactingCardIndex);
		}
	}

	// --- 2. BUILD ZMQ PAYLOAD ---
	std::vector<float> payload;
	payload.reserve(2 + state.size() + actionMask.size());
	payload.push_back(done ? 1.0f : 0.0f);
	payload.push_back(reward);
	payload.insert(payload.end(), state.begin(), state.end());
	payload.insert(payload.end(), actionMask.begin(), actionMask.end());

	// --- 3. COMMUNICATE WITH PYTHON ---
	zmq::message_t request(payload.size() * sizeof(float));
	memcpy(request.data(), payload.data(), payload.size() * sizeof(float));
	zmqSocket->send(request, zmq::send_flags::none);

	zmq::message_t reply;
	auto res = zmqSocket->recv(reply, zmq::recv_flags::none);

	if (res.has_value()) {
		int action = -1;
		memcpy(&action, reply.data(), sizeof(int));
		return action;
	}
	return 0;
}

void ofApp::executeAIAction(int actionIndex) {
	InputCommandPacket cmd = {};
	cmd.type = PKT_INPUT_COMMAND;

	// In AI vs AI, we command whoever is currently active.
	cmd.playerID = isAIvsAI ? (players[currentPlayerIndex].isMinion ? players[currentPlayerIndex].ownerID : players[currentPlayerIndex].playerID) : 1;

	cmd.commandId = nextCommandId++;
	cmd.turnNumber = globalTurnCounter;

	if (actionIndex == 0) {
		// Action 0: End Turn
		cmd.commandType = CMD_END_TURN;
		sendInputCommand(cmd, true);
		endTurnLocked = true;
	} else if (actionIndex == 1) {
		// Action 1: Draw Cards
		cmd.commandType = CMD_DRAW_CARDS;
		cmd.params[0] = currentPlayerIndex;
		cmd.params[1] = players[currentPlayerIndex].isDemon ? 3 : 2;
		sendInputCommand(cmd, true);
	} else if (actionIndex == 2) {
		// Action 2: Assistant AP Reroll
		int assistantIndex = -1;
		for (int i = 0; i < (int)players.size(); i++) {
			if (players[i].isAssistant && players[i].health > 0 && players[i].directSummonerID == players[currentPlayerIndex].playerID && !players[i].assistantRerollUsedThisTurn) {
				if (abs(players[i].x - players[currentPlayerIndex].x) + abs(players[i].y - players[currentPlayerIndex].y) <= 1) {
					assistantIndex = i;
					break;
				}
			}
		}
		if (assistantIndex != -1) {
			cmd.commandType = CMD_PSEUDO_ACTION;
			cmd.params[0] = assistantIndex;
			strncpy(cmd.stringData, "AssistantReroll", sizeof(cmd.stringData) - 1);
			sendInputCommand(cmd, true);
		}
	} else if (actionIndex >= 10 && actionIndex <= 29) {
		// Action 10-29: Menu Choices (Choice 1 through 10)
		int choice = (actionIndex - 10) + 1; // Menus usually 1-based (1 or 2)
		if (interactingCardType == PSEUDO_CARD_GHOST_RELOCATE) choice -= 1; // Ghost relocate is 0-based

		cmd.commandType = CMD_MENU_CHOICE;
		cmd.params[0] = interactingCardType;
		cmd.params[1] = interactionTargetIndex;
		cmd.params[2] = choice;
		cmd.params[3] = interactingCardIndex;
		if (interactingCardType == CARD_GIANT_MAGIC_HAND) {
			cmd.params[4] = magicHandTargetTile.x;
			cmd.params[5] = magicHandTargetTile.y;
		}
		sendInputCommand(cmd, true);
	} else if (actionIndex >= 30 && actionIndex <= 32) {
		// Action 30-32: Draft Selection (Combinations)
		int draftPick = actionIndex - 30; // 0, 1, or 2
		if (currentDraftOptionPoolIndices.size() >= 3) {
			cmd.commandType = CMD_ACCEPT_DRAFT;
			cmd.params[0] = draftPlayerIndex;
			cmd.params[1] = currentDraftClassTier;

			if (!isInGameDraft && draftStage == 0) {
				// Initial Draft Phase 1 (Class 1): Must pick 2 Cards (gets 2 copies each)
				cmd.params[2] = 2; // Copies
				// AI combinations: 0=[0,1], 1=[0,2], 2=[1,2]
				if (draftPick == 0) {
					cmd.params[3] = currentDraftOptionPoolIndices[0];
					cmd.params[4] = currentDraftOptionPoolIndices[1];
				} else if (draftPick == 1) {
					cmd.params[3] = currentDraftOptionPoolIndices[0];
					cmd.params[4] = currentDraftOptionPoolIndices[2];
				} else {
					cmd.params[3] = currentDraftOptionPoolIndices[1];
					cmd.params[4] = currentDraftOptionPoolIndices[2];
				}
				cmd.params[5] = -1;
			} else {
				// Initial Draft Phase 2 (Class 2) or In-Game Draft: Pick 1 card (gets 1 copy)
				cmd.params[2] = 1; // Copies
				cmd.params[3] = currentDraftOptionPoolIndices[draftPick];
				cmd.params[4] = -1;
				cmd.params[5] = -1;
			}

			sendInputCommand(cmd, true);
			draftAcceptLocked = true;
		}
	} else if (actionIndex >= 40 && actionIndex <= 139) {
		// Action 40-139: Toggle Amnesia/Renewed Inspiration UI Cards
		int toggleIdx = actionIndex - 40;
		if (cardInteractionState == CARD_INTERACTION_STATE_MENU) {
			if (interactingCardType == CARD_AMNESIA) {
				auto it = std::find(amnesiaSelectedIndices.begin(), amnesiaSelectedIndices.end(), toggleIdx);
				if (it != amnesiaSelectedIndices.end())
					amnesiaSelectedIndices.erase(it);
				else if (amnesiaSelectedIndices.size() < (size_t)numCardsToRemove)
					amnesiaSelectedIndices.push_back(toggleIdx);
			} else if (interactingCardType == CARD_RENEWED_INSPIRATION) {
				auto it = std::find(renewedSelectedHandIndices.begin(), renewedSelectedHandIndices.end(), toggleIdx);
				if (it != renewedSelectedHandIndices.end())
					renewedSelectedHandIndices.erase(it);
				else
					renewedSelectedHandIndices.push_back(toggleIdx);
			}
		}
	} else if (actionIndex == 140) {
		// Action 140: Click the Accept Button for Amnesia / Renewed Inspiration
		if (cardInteractionState == CARD_INTERACTION_STATE_MENU) {
			if (interactingCardType == CARD_AMNESIA && amnesiaSelectedIndices.size() == (size_t)numCardsToRemove) {
				cmd.commandType = CMD_MENU_CHOICE;
				cmd.params[0] = (int)CARD_AMNESIA;
				cmd.params[1] = amnesiaTargetPlayerIndex;
				cmd.params[2] = 3;
				cmd.params[4] = amnesiaSelectedIndices.size();
				for (int i = 0; i < std::min(3, (int)amnesiaSelectedIndices.size()); ++i)
					cmd.params[5 + i] = amnesiaSelectedIndices[i];

				std::string s;
				for (size_t i = 0; i < amnesiaSelectedIndices.size(); ++i) {
					if (i) s += ",";
					s += std::to_string(amnesiaSelectedIndices[i]);
				}
				strncpy(cmd.stringData, s.c_str(), sizeof(cmd.stringData) - 1);
				sendInputCommand(cmd, true);
				amnesiaDeckCopy.clear();
				amnesiaSelectedIndices.clear();
				resetCardInteraction();
			} else if (interactingCardType == CARD_RENEWED_INSPIRATION) {
				cmd.commandType = CMD_RENEWED_INSPIRATION;
				cmd.params[0] = currentPlayerIndex;
				cmd.params[1] = renewedSelectedHandIndices.size();
				cmd.params[2] = interactingCardIndex;

				std::string s;
				for (size_t i = 0; i < renewedSelectedHandIndices.size(); ++i) {
					if (i) s += ",";
					s += std::to_string(renewedSelectedHandIndices[i]);
				}
				strncpy(cmd.stringData, s.c_str(), sizeof(cmd.stringData) - 1);
				sendInputCommand(cmd, true);
				renewedSelectedHandIndices.clear();
				resetCardInteraction();
			}
		}
	} else if (actionIndex >= 200 && actionIndex <= 364) {
		// Action 200-364: Move Current Unit to specific Tile Index (0-164)
		int tileIdx = actionIndex - 200;
		int tx = tileIdx % BOARD_WIDTH; // 0 to 14
		int ty = tileIdx / BOARD_WIDTH; // 0 to 10

		cmd.commandType = CMD_MOVE_UNIT;
		cmd.params[0] = players[currentPlayerIndex].x;
		cmd.params[1] = players[currentPlayerIndex].y;
		cmd.params[2] = tx;
		cmd.params[3] = ty;
		sendInputCommand(cmd, true);
	} else if (actionIndex >= 1000 && actionIndex <= 1164) {
		// Action 1000-1164: Raw Target Click on Tile Index (0-164)
		// Used for resolving Teleport destinations, Shell Spike, and Kobold/Wolf Placement
		int tileIdx = actionIndex - 1000;
		int tx = tileIdx % BOARD_WIDTH;
		int ty = tileIdx / BOARD_WIDTH;
		handleCardTargetClick(tx, ty);
	} else if (actionIndex >= 10000) {
		// Action 10000+: Play Card from Hand at (X, Y)
		// We decode the single integer back into HandIndex, X, and Y
		int encodedVal = actionIndex - 10000;
		int tileIdx = encodedVal % (BOARD_WIDTH * BOARD_HEIGHT); // 0 to 164
		int handIndex = encodedVal / (BOARD_WIDTH * BOARD_HEIGHT); // 0 to MaxHandSize

		int tx = tileIdx % BOARD_WIDTH;
		int ty = tileIdx / BOARD_WIDTH;

		cmd.commandType = CMD_PLAY_CARD;
		cmd.params[0] = handIndex;
		cmd.params[1] = tx;
		cmd.params[2] = ty;
		sendInputCommand(cmd, true);
	}
}

// Anti-cheat: Log all player deck states to file and console
void ofApp::logDeckStates(const std::string & reason) {
	std::string timestamp = ofGetTimestampString("%Y-%m-%d %H:%M:%S");
	std::string logEntry = "\n=== DECK STATE LOG ===\n";
	logEntry += "Time: " + timestamp + "\n";
	logEntry += "Reason: " + reason + "\n";
	logEntry += "Turn: " + std::to_string(globalTurnCounter) + "\n";
	logEntry += "Current Player: " + std::to_string(currentPlayerIndex) + "\n";
	logEntry += "Local Player ID: " + std::to_string(myLocalPlayerID) + "\n";
	logEntry += "Is Host: " + std::string(steamManager.isHost() ? "true" : "false") + "\n\n";

	for (const auto & p : players) {
		logEntry += getDeckStateString(p) + "\n";
	}
	logEntry += "=====================\n";

	// Log to console
	ofLogNotice("DeckState") << logEntry;

	// Append to file
	std::string filename = "deck_states_" + std::string(steamManager.isHost() ? "host" : "client") + ".log";
	ofBuffer buffer;
	buffer.set(logEntry.c_str(), logEntry.size());

	ofBufferToFile(filename, buffer, true); // true = append mode
}

// Simple deterministic dice resolver used by a few inline spawn paths.
int ofApp::resolveDiceRoll(int numDice, int sides) {
	int total = 0;
	for (int i = 0; i < numDice; ++i) {
		total += getGameRandom(1, sides);
	}
	return total;
}

// Detailed resolver that returns per-die raw faces and the sum of raw faces.
int ofApp::resolveDiceRollDetailed(int numDice, int sides, std::vector<int> & outRaw) {
	outRaw.clear();
	int totalRaw = 0;
	for (int i = 0; i < numDice; ++i) {
		int raw = getGameRandom(1, sides);
		outRaw.push_back(raw);
		totalRaw += raw;
	}
	return totalRaw;
}

void ofApp::saveReplay(const std::string & filename) {
	ofJson j;
	j["seed"] = currentMapSeed;
	j["player0"] = player0SteamName;
	j["player1"] = player1SteamName;

	ofJson cmds = ofJson::array();
	for (const auto & rc : matchReplayLog) {
		ofJson cj;
		cj["frame"] = rc.frame;
		cj["cmdId"] = rc.cmd.commandId;
		cj["turn"] = rc.cmd.turnNumber;
		cj["type"] = rc.cmd.commandType;
		cj["player"] = rc.cmd.playerID;
		cj["p0"] = rc.cmd.params[0];
		cj["p1"] = rc.cmd.params[1];
		cj["p2"] = rc.cmd.params[2];
		cj["p3"] = rc.cmd.params[3];
		cj["p4"] = rc.cmd.params[4];
		cj["p5"] = rc.cmd.params[5];
		cj["p6"] = rc.cmd.params[6];
		cj["p7"] = rc.cmd.params[7];
		cj["str"] = std::string(rc.cmd.stringData);
		cmds.push_back(cj);
	}
	j["commands"] = cmds;

	std::string path = getSavesDirPath().string() + "/" + filename;
	ofSaveJson(path, j);
	ofLogNotice("Replay") << "Saved replay to " << path;
}

void ofApp::loadReplay(const std::string & filename) {
	std::string path = getSavesDirPath().string() + "/" + filename;
	ofJson j = ofLoadJson(path);
	if (j.empty()) {
		ofLogError("Replay") << "Failed to load replay: " << path;
		return;
	}

	isReplayMode = true;
	isMultiplayer = false; // Replays play back entirely offline

	currentMapSeed = j.value("seed", 0);
	player0SteamName = j.value("player0", "Player 1");
	player1SteamName = j.value("player1", "Player 2");

	replayPlaybackQueue.clear();
	for (const auto & cj : j["commands"]) {
		ReplayCommand rc;
		rc.frame = cj.value("frame", 0);
		rc.cmd.commandId = cj.value("cmdId", 0);
		rc.cmd.turnNumber = cj.value("turn", 0);
		rc.cmd.commandType = cj.value("type", 0);
		rc.cmd.playerID = cj.value("player", 0);
		rc.cmd.params[0] = cj.value("p0", 0);
		rc.cmd.params[1] = cj.value("p1", 0);
		rc.cmd.params[2] = cj.value("p2", 0);
		rc.cmd.params[3] = cj.value("p3", 0);
		rc.cmd.params[4] = cj.value("p4", 0);
		rc.cmd.params[5] = cj.value("p5", 0);
		rc.cmd.params[6] = cj.value("p6", 0);
		rc.cmd.params[7] = cj.value("p7", 0);

		std::string str = cj.value("str", "");
		strncpy(rc.cmd.stringData, str.c_str(), sizeof(rc.cmd.stringData) - 1);
		rc.cmd.stringData[sizeof(rc.cmd.stringData) - 1] = '\0';

		replayPlaybackQueue.push_back(rc);
	}

	replayPlaybackIndex = 0;
	setupGame(); // Start the game with the forced seed
	addGameLog("Replay loaded! Watching...");
}